    'battery_opt_android': 'אנדרואיד',
    'battery_opt_close': 'סגור',
    'battery_opt_device_prefix': 'מכשיר: ',
    'battery_opt_intro': 'אם השידור שלך נעצר כשאתה פותח את המשחק, הטלפון שלך סוגר את האפליקציה ברקע.\nבצע את השלבים האלה פעם אחת:',
    'battery_opt_notes_body': '• חלק מהמשחקים חוסמים הקלטת מסך (תוכן מוגן). במקרה כזה הצופים עשויים לראות מסך שחור.\n• השאר את התראת השידור פעילה במהלך שידור חי.\n• לתוצאות הטובות ביותר, אל "תעצור בכוח" את האפליקציה במהלך שידור חי.',
    'battery_opt_notes_title': 'הערות:',
    'battery_opt_open_app_settings_btn': 'פתח הגדרות אפליקציה (הפעלה אוטומטית / רקע)',
    'battery_opt_open_battery_settings_btn': 'פתח הגדרות אופטימיזציית סוללה',
    'battery_opt_quick_buttons': 'כפתורים מהירים:',
    'battery_opt_request_ignore_btn': 'בקש "התעלם מאופטימיזציית סוללה"',
    'battery_opt_steps_generic': '\nאנדרואיד כללי:\n1) הגדרות ← סוללה ← אופטימיזציית סוללה\n2) מצא את האפליקציה הזו ← הגדר ל"אל תבצע אופטימיזציה"\n3) הגדרות ← אפליקציות ← (אפליקציה זו) ← סוללה ← אפשר פעילות ברקע\n4) אם יש הגדרות הפעלה אוטומטית, הפעל אותן עבור אפליקציה זו\n',
    'battery_opt_steps_huawei': '\nHuawei / Honor:\n1) הגדרות ← סוללה ← הפעלת אפליקציות\n2) מצא את האפליקציה הזו ← הגדר ל"ניהול ידני"\n3) הפעל: הפעלה אוטומטית, הפעלה משנית, פעולה ברקע\n',
    'battery_opt_steps_oppo': '\nOPPO / realme / OnePlus:\n1) הגדרות ← סוללה ← הגדרות סוללה נוספות / ניהול סוללת אפליקציות\n2) מצא את האפליקציה הזו ← אפשר פעילות ברקע\n3) הפעל גם הפעלה אוטומטית (לרוב ב: הגדרות ← אפליקציות ← הפעלה אוטומטית)\n',
    'battery_opt_steps_samsung': '\nSamsung:\n1) הגדרות ← סוללה וטיפול במכשיר ← סוללה\n2) מגבלות שימוש ברקע ← אפליקציות שלא נכנסות לשינה ← הוסף אפליקציה זו\n3) בדוק גם: הגדרות ← אפליקציות ← (אפליקציה זו) ← סוללה ← אפשר פעילות ברקע\n',
    'battery_opt_steps_transsion': '\nInfinix / Tecno / itel (HiOS/XOS):\n1) הגדרות ← סוללה / Power Marathon ← כבה חיסכון אגרסיבי עבור אפליקציה זו\n2) הגדרות ← אפליקציות ← (אפליקציה זו) ← סוללה ← אפשר פעילות ברקע\n3) הפעל הפעלה אוטומטית / הפעלה ברקע אם זמין\n4) הוסף את האפליקציה גם לרשימה הלבנה ב-"Phone Master" / "Device Manager"\n',
