    'battery_opt_notes_body': '• Algunos juegos bloquean la captura de pantalla (contenido protegido). En ese caso los espectadores pueden ver una pantalla negra.\n• Mantén activa la notificación de transmisión mientras emites en vivo.\n• Para mejores resultados, no "fuerces el cierre" de la app durante una transmisión en vivo.',
