    'battery_opt_steps_generic': '\nAndroid genérico:\n1) Ajustes → Batería → Optimización de batería\n2) Busca esta app → configúrala como "No optimizar"\n3) Ajustes → Aplicaciones → (esta app) → Batería → Permitir actividad en segundo plano\n4) Si tienes ajustes de inicio automático, actívalos para esta app\n',
    'battery_opt_steps_huawei': '\nHuawei / Honor:\n1) Ajustes → Batería → Inicio de apps\n2) Busca esta app → configúrala como "Gestionar manualmente"\n3) Activa: Inicio automático, Inicio secundario, Ejecutar en segundo plano\n',
    'battery_opt_steps_oppo': '\nOPPO / realme / OnePlus:\n1) Ajustes → Batería → Más ajustes de batería / Gestión de batería de apps\n2) Busca esta app → Permitir actividad en segundo plano\n3) Activa también el inicio automático (normalmente en: Ajustes → Aplicaciones → Inicio automático)\n',
    'battery_opt_steps_samsung': '\nSamsung:\n1) Ajustes → Batería y cuidado del dispositivo → Batería\n2) Límites de uso en segundo plano → Apps que nunca duermen → añade esta app\n3) Revisa también: Ajustes → Aplicaciones → (esta app) → Batería → Permitir actividad en segundo plano\n',
    'battery_opt_steps_transsion': '\nInfinix / Tecno / itel (HiOS/XOS):\n1) Ajustes → Batería / Power Marathon → desactiva el ahorro agresivo para esta app\n2) Ajustes → Aplicaciones → (esta app) → Batería → Permitir actividad en segundo plano\n3) Activa el inicio automático / en segundo plano si está disponible\n4) Añade también la app a la lista blanca en "Phone Master" / "Device Manager"\n',
