    'battery_opt_close': 'Fermer',
    'battery_opt_device_prefix': 'Appareil : ',
    'battery_opt_intro': 'Si votre diffusion s’arrête à l’ouverture du jeu, votre téléphone ferme l’application en arrière-plan.\nSuivez ces étapes une fois :',
    'battery_opt_notes_body': '• Certains jeux bloquent la capture d’écran (contenu protégé). Dans ce cas, les spectateurs peuvent voir un écran noir.\n• Laissez la notification de diffusion active pendant la diffusion en direct.\n• Pour de meilleurs résultats, ne « forcez pas l’arrêt » de l’application pendant une diffusion en direct.',
    'battery_opt_notes_title': 'Remarques :',
    'battery_opt_open_app_settings_btn': 'OUVRIR LES PARAMÈTRES DE L’APPLICATION (DÉMARRAGE AUTO / ARRIÈRE-PLAN)',
    'battery_opt_open_battery_settings_btn': 'OUVRIR LES PARAMÈTRES D’OPTIMISATION DE LA BATTERIE',
    'battery_opt_quick_buttons': 'Boutons rapides :',
    'battery_opt_request_ignore_btn': 'DEMANDER « IGNORER L’OPTIMISATION DE LA BATTERIE »',
    'battery_opt_steps_generic': '\nAndroid générique :\n1) Paramètres → Batterie → Optimisation de la batterie\n2) Trouvez cette application → réglez sur « Ne pas optimiser »\n3) Paramètres → Applications → (cette application) → Batterie → Autoriser l’activité en arrière-plan\n4) Si des paramètres de démarrage automatique existent, activez-les pour cette application\n',
    'battery_opt_steps_huawei': '\nHuawei / Honor :\n1) Paramètres → Batterie → Lancement des applications\n2) Trouvez cette application → réglez sur « Gérer manuellement »\n3) Activez : Lancement automatique, Lancement secondaire, Exécution en arrière-plan\n',
    'battery_opt_steps_oppo': '\nOPPO / realme / OnePlus :\n1) Paramètres → Batterie → Plus de paramètres de batterie / Gestion de la batterie des applications\n2) Trouvez cette application → Autoriser l’activité en arrière-plan\n3) Activez aussi le démarrage automatique (souvent dans : Paramètres → Applications → Démarrage automatique)\n',
    'battery_opt_steps_samsung': '\nSamsung :\n1) Paramètres → Batterie et entretien de l’appareil → Batterie\n2) Limites d’utilisation en arrière-plan → Applications non mises en veille → ajoutez cette application\n3) Vérifiez aussi : Paramètres → Applications → (cette application) → Batterie → Autoriser l’activité en arrière-plan\n',
    'battery_opt_steps_transsion': '\nInfinix / Tecno / itel (HiOS/XOS) :\n1) Paramètres → Batterie / Power Marathon → désactivez l’économie agressive pour cette application\n2) Paramètres → Applications → (cette application) → Batterie → Autoriser l’activité en arrière-plan\n3) Activez le démarrage automatique / en arrière-plan si disponible\n4) Ajoutez aussi l’application à la liste blanche dans « Phone Master » / « Device Manager »\n',
    'battery_opt_title': 'Corriger la diffusion en arrière-plan (optimisation de la batterie)',
