    'battery_opt_android': 'Android',
    'battery_opt_close': 'Закрыть',
    'battery_opt_device_prefix': 'Устройство: ',
    'battery_opt_intro': 'Если трансляция останавливается при открытии игры, значит телефон закрывает приложение в фоне.\nВыполните эти шаги один раз:',
    'battery_opt_notes_body': '• Некоторые игры блокируют запись экрана (защищённый контент). В этом случае зрители могут увидеть чёрный экран.\n• Держите уведомление о трансляции включённым во время прямого эфира.\n• Для лучшего результата не «принудительно останавливайте» приложение во время прямого эфира.',
    'battery_opt_notes_title': 'Примечания:',
    'battery_opt_open_app_settings_btn': 'ОТКРЫТЬ НАСТРОЙКИ ПРИЛОЖЕНИЯ (АВТОЗАПУСК / ФОН)',
    'battery_opt_open_battery_settings_btn': 'ОТКРЫТЬ НАСТРОЙКИ ОПТИМИЗАЦИИ БАТАРЕИ',
    'battery_opt_quick_buttons': 'Быстрые кнопки:',
    'battery_opt_request_ignore_btn': 'ЗАПРОСИТЬ «НЕ ОПТИМИЗИРОВАТЬ БАТАРЕЮ»',
    'battery_opt_steps_generic': '\nAndroid (общий вариант):\n1) Настройки → Батарея → Оптимизация батареи\n2) Найдите это приложение → установите «Не оптимизировать»\n3) Настройки → Приложения → (это приложение) → Батарея → Разрешить работу в фоне\n4) Если есть настройки автозапуска, включите их для этого приложения\n',
    'battery_opt_steps_huawei': '\nHuawei / Honor:\n1) Настройки → Батарея → Запуск приложений\n2) Найдите это приложение → установите «Управлять вручную»\n3) Включите: Автозапуск, Вторичный запуск, Работа в фоне\n',
    'battery_opt_steps_oppo': '\nOPPO / realme / OnePlus:\n1) Настройки → Батарея → Дополнительные настройки батареи / Управление батареей приложений\n2) Найдите это приложение → Разрешить работу в фоне\n3) Также включите автозапуск (обычно в: Настройки → Приложения → Автозапуск)\n',
    'battery_opt_steps_samsung': '\nSamsung:\n1) Настройки → Батарея и обслуживание устройства → Батарея\n2) Ограничения фоновой активности → Приложения, которые никогда не «спят» → добавьте это приложение\n3) Также проверьте: Настройки → Приложения → (это приложение) → Батарея → Разрешить работу в фоне\n',
    'battery_opt_steps_transsion': '\nInfinix / Tecno / itel (HiOS/XOS):\n1) Настройки → Батарея / Power Marathon → отключите агрессивную экономию для этого приложения\n2) Настройки → Приложения → (это приложение) → Батарея → Разрешить работу в фоне\n3) Включите автозапуск / фоновый запуск, если доступно\n4) Также добавьте приложение в белый список в «Phone Master» / «Device Manager»\n',
    'battery_opt_title': 'Исправить фоновую трансляцию (оптимизация батареи)',
    'common_clear': 'Очистить',
