    'battery_opt_android': 'Android',
    'battery_opt_close': 'Funga',
    'battery_opt_device_prefix': 'Kifaa: ',
    'battery_opt_intro': 'Iwapo mtiririko wako unasimama unapofungua mchezo, simu yako inazima programu ikiwa nyuma.\nFanya hatua hizi mara moja:',
    'battery_opt_notes_body': '• Baadhi ya michezo huzuia kunasa skrini (maudhui yaliyolindwa). Katika hali hiyo watazamaji wanaweza kuona skrini nyeusi.\n• Weka arifa ya mtiririko IKIWA WASHA wakati wa matangazo ya moja kwa moja.\n• Kwa matokeo bora, usi"lazimishe kusimamisha" programu wakati wa mtiririko wa moja kwa moja.',
    'battery_opt_notes_title': 'Vidokezo:',
    'battery_opt_open_app_settings_btn': 'FUNGUA MIPANGILIO YA PROGRAMU (UANZISHAJI WA OTOMATIKI / NYUMA)',
    'battery_opt_open_battery_settings_btn': 'FUNGUA MIPANGILIO YA UBORESHAJI WA BETRI',
    'battery_opt_quick_buttons': 'Vitufe vya haraka:',
    'battery_opt_request_ignore_btn': 'OMBA "PUUZA UBORESHAJI WA BETRI"',
    'battery_opt_steps_generic': '\nAndroid ya Kawaida:\n1) Mipangilio → Betri → Uboreshaji wa Betri\n2) Tafuta programu hii → weka "Usiboreshe"\n3) Mipangilio → Programu → (programu hii) → Betri → Ruhusu shughuli ya nyuma\n4) Ikiwa una mipangilio ya kuanzisha kiotomatiki, iwashe kwa programu hii\n',
    'battery_opt_steps_huawei': '\nHuawei / Honor:\n1) Mipangilio → Betri → Uzinduzi wa programu\n2) Tafuta programu hii → weka "Simamia mwenyewe"\n3) Washa: Uzinduzi wa kiotomatiki, Uzinduzi wa pili, Kufanya kazi nyuma\n',
    'battery_opt_steps_oppo': '\nOPPO / realme / OnePlus:\n1) Mipangilio → Betri → Mipangilio zaidi ya betri / Usimamizi wa betri wa programu\n2) Tafuta programu hii → Ruhusu shughuli ya nyuma\n3) Washa pia uzinduzi wa kiotomatiki (mara nyingi katika: Mipangilio → Programu → Uzinduzi wa kiotomatiki)\n',
    'battery_opt_steps_samsung': '\nSamsung:\n1) Mipangilio → Betri na huduma ya kifaa → Betri\n2) Mipaka ya matumizi ya nyuma → Programu zisizolala kamwe → ongeza programu hii\n3) Angalia pia: Mipangilio → Programu → (programu hii) → Betri → Ruhusu shughuli ya nyuma\n',
    'battery_opt_steps_transsion': '\nInfinix / Tecno / itel (HiOS/XOS):\n1) Mipangilio → Betri / Power Marathon → zima uhifadhi mkali kwa programu hii\n2) Mipangilio → Programu → (programu hii) → Betri → Ruhusu shughuli ya nyuma\n3) Washa Uzinduzi wa kiotomatiki / Uzinduzi wa nyuma ikiwa upo\n4) Ongeza pia programu kwenye orodha nyeupe katika "Phone Master" / "Device Manager"\n',
    'battery_opt_title': 'Rekebisha Mtiririko wa Nyuma (Uboreshaji wa Betri)',
