    'battery_opt_android': 'Android',
    'battery_opt_close': 'Tutup',
    'battery_opt_device_prefix': 'Perangkat: ',
    'battery_opt_intro': 'Jika siaran Anda berhenti saat membuka game, ponsel Anda menghentikan aplikasi di latar belakang.\nLakukan langkah-langkah ini sekali:',
    'battery_opt_notes_body': '• Beberapa game memblokir perekaman layar (konten terlindungi). Dalam hal ini penonton mungkin melihat layar hitam.\n• Jaga notifikasi siaran tetap AKTIF selama siaran langsung.\n• Untuk hasil terbaik, jangan "Paksa berhenti" aplikasi selama siaran langsung.',
    'battery_opt_notes_title': 'Catatan:',
    'battery_opt_open_app_settings_btn': 'BUKA SETELAN APLIKASI (MULAI OTOMATIS / LATAR BELAKANG)',
    'battery_opt_open_battery_settings_btn': 'BUKA SETELAN OPTIMASI BATERAI',
    'battery_opt_quick_buttons': 'Tombol cepat:',
    'battery_opt_request_ignore_btn': 'MINTA "ABAIKAN OPTIMASI BATERAI"',
    'battery_opt_steps_generic': '\nAndroid Umum:\n1) Setelan → Baterai → Optimasi baterai\n2) Cari aplikasi ini → atur ke "Jangan optimalkan"\n3) Setelan → Aplikasi → (aplikasi ini) → Baterai → Izinkan aktivitas latar belakang\n4) Jika ada setelan mulai otomatis, aktifkan untuk aplikasi ini\n',
    'battery_opt_steps_huawei': '\nHuawei / Honor:\n1) Setelan → Baterai → Peluncuran aplikasi\n2) Cari aplikasi ini → atur ke "Kelola secara manual"\n3) Aktifkan: Mulai otomatis, Mulai sekunder, Berjalan di latar belakang\n',
    'battery_opt_steps_oppo': '\nOPPO / realme / OnePlus:\n1) Setelan → Baterai → Setelan baterai lainnya / Manajemen baterai aplikasi\n2) Cari aplikasi ini → Izinkan aktivitas latar belakang\n3) Aktifkan juga mulai otomatis (biasanya di: Setelan → Aplikasi → Mulai otomatis)\n',
    'battery_opt_steps_samsung': '\nSamsung:\n1) Setelan → Baterai dan perawatan perangkat → Baterai\n2) Batasan penggunaan latar belakang → Aplikasi yang tidak pernah tidur → tambahkan aplikasi ini\n3) Periksa juga: Setelan → Aplikasi → (aplikasi ini) → Baterai → Izinkan aktivitas latar belakang\n',
    'battery_opt_steps_transsion': '\nInfinix / Tecno / itel (HiOS/XOS):\n1) Setelan → Baterai / Power Marathon → matikan penghematan agresif untuk aplikasi ini\n2) Setelan → Aplikasi → (aplikasi ini) → Baterai → Izinkan aktivitas latar belakang\n3) Aktifkan Mulai otomatis / Peluncuran latar belakang jika tersedia\n4) Tambahkan juga aplikasi ke daftar putih di "Phone Master" / "Device Manager"\n',
    'battery_opt_title': 'Perbaiki Siaran Latar Belakang (Optimasi Baterai)',
