    'battery_opt_android': 'Android',
    'battery_opt_close': '閉じる',
    'battery_opt_device_prefix': '端末: ',
    'battery_opt_intro': 'ゲームを開くと配信が止まる場合、スマートフォンがバックグラウンドでアプリを終了させています。\n以下の手順を一度だけ行ってください:',
    'battery_opt_notes_body': '• 一部のゲームは画面キャプチャをブロックします(保護されたコンテンツ)。この場合、視聴者には黒い画面が表示されることがあります。\n• ライブ配信中は配信通知をONのままにしてください。\n• 最良の結果を得るには、ライブ配信中にアプリを「強制終了」しないでください。',
    'battery_opt_notes_title': '注意事項:',
    'battery_opt_open_app_settings_btn': 'アプリ設定を開く(自動起動 / バックグラウンド)',
    'battery_opt_open_battery_settings_btn': 'バッテリー最適化設定を開く',
    'battery_opt_quick_buttons': 'クイックボタン:',
    'battery_opt_request_ignore_btn': '「バッテリー最適化を無視」をリクエスト',
    'battery_opt_steps_generic': '\n一般的なAndroid:\n1) 設定 → バッテリー → バッテリー最適化\n2) このアプリを探す → 「最適化しない」に設定\n3) 設定 → アプリ → (このアプリ) → バッテリー → バックグラウンド動作を許可\n4) 自動起動設定がある場合は、このアプリで有効にする\n',
    'battery_opt_steps_huawei': '\nHuawei / Honor:\n1) 設定 → バッテリー → アプリの起動\n2) このアプリを探す → 「手動で管理」に設定\n3) 有効にする: 自動起動、二次起動、バックグラウンド実行\n',
    'battery_opt_steps_oppo': '\nOPPO / realme / OnePlus:\n1) 設定 → バッテリー → その他のバッテリー設定 / アプリのバッテリー管理\n2) このアプリを探す → バックグラウンド動作を許可\n3) 自動起動も有効にする(通常: 設定 → アプリ → 自動起動)\n',
    'battery_opt_steps_samsung': '\nSamsung:\n1) 設定 → バッテリーとデバイスケア → バッテリー\n2) バックグラウンド使用の制限 → スリープしないアプリ → このアプリを追加\n3) 確認: 設定 → アプリ → (このアプリ) → バッテリー → バックグラウンド動作を許可\n',
    'battery_opt_steps_transsion': '\nInfinix / Tecno / itel (HiOS/XOS):\n1) 設定 → バッテリー / パワーマラソン → このアプリの積極的な節電をオフにする\n2) 設定 → アプリ → (このアプリ) → バッテリー → バックグラウンド動作を許可\n3) 可能であれば自動起動 / バックグラウンド起動を有効にする\n4) 「Phone Master」/「Device Manager」でもこのアプリをホワイトリストに追加する\n',
    'battery_opt_title': 'バックグラウンド配信を修正(バッテリー最適化)',
