    'battery_opt_android': 'Android',
    'battery_opt_close': '닫기',
    'battery_opt_device_prefix': '기기: ',
    'battery_opt_intro': '게임을 열 때 방송이 중단된다면, 휴대폰이 백그라운드에서 앱을 종료하고 있는 것입니다.\n다음 단계를 한 번만 수행하세요:',
    'battery_opt_notes_body': '• 일부 게임은 화면 캡처를 차단합니다(보호된 콘텐츠). 이 경우 시청자에게 검은 화면이 보일 수 있습니다.\n• 라이브 방송 중에는 방송 알림을 계속 켜두세요.\n• 최상의 결과를 위해 라이브 방송 중에는 앱을 "강제 종료"하지 마세요.',
    'battery_opt_notes_title': '참고 사항:',
    'battery_opt_open_app_settings_btn': '앱 설정 열기(자동 시작 / 백그라운드)',
    'battery_opt_open_battery_settings_btn': '배터리 최적화 설정 열기',
    'battery_opt_quick_buttons': '빠른 버튼:',
    'battery_opt_request_ignore_btn': '"배터리 최적화 무시" 요청',
    'battery_opt_steps_generic': '\n일반 Android:\n1) 설정 → 배터리 → 배터리 최적화\n2) 이 앱을 찾아 → "최적화하지 않음"으로 설정\n3) 설정 → 앱 → (이 앱) → 배터리 → 백그라운드 활동 허용\n4) 자동 시작 설정이 있다면 이 앱에 대해 활성화하세요\n',
    'battery_opt_steps_huawei': '\nHuawei / Honor:\n1) 설정 → 배터리 → 앱 실행\n2) 이 앱을 찾아 → "수동으로 관리"로 설정\n3) 활성화: 자동 실행, 보조 실행, 백그라운드 실행\n',
    'battery_opt_steps_oppo': '\nOPPO / realme / OnePlus:\n1) 설정 → 배터리 → 추가 배터리 설정 / 앱 배터리 관리\n2) 이 앱을 찾아 → 백그라운드 활동 허용\n3) 자동 실행도 활성화하세요(대개: 설정 → 앱 → 자동 실행)\n',
    'battery_opt_steps_samsung': '\nSamsung:\n1) 설정 → 배터리 및 디바이스 케어 → 배터리\n2) 백그라운드 사용 제한 → 절전 모드 사용 안 함 앱 → 이 앱 추가\n3) 다음도 확인하세요: 설정 → 앱 → (이 앱) → 배터리 → 백그라운드 활동 허용\n',
    'battery_opt_steps_transsion': '\nInfinix / Tecno / itel (HiOS/XOS):\n1) 설정 → 배터리 / Power Marathon → 이 앱에 대한 적극적인 절전 끄기\n2) 설정 → 앱 → (이 앱) → 배터리 → 백그라운드 활동 허용\n3) 가능하다면 자동 실행 / 백그라운드 실행 활성화\n4) "Phone Master" / "Device Manager"에서도 이 앱을 화이트리스트에 추가하세요\n',
    'battery_opt_title': '백그라운드 방송 문제 해결(배터리 최적화)',
