    'battery_opt_android': 'Android',
    'battery_opt_close': 'Fechar',
    'battery_opt_device_prefix': 'Dispositivo: ',
    'battery_opt_intro': 'Se sua transmissão parar ao abrir o jogo, seu celular está encerrando o app em segundo plano.\nSiga estes passos uma vez:',
    'battery_opt_notes_body': '• Alguns jogos bloqueiam a gravação de tela (conteúdo protegido). Nesse caso, os espectadores podem ver uma tela preta.\n• Mantenha a notificação de transmissão ATIVADA durante a transmissão ao vivo.\n• Para melhores resultados, não "force o encerramento" do app durante uma transmissão ao vivo.',
    'battery_opt_notes_title': 'Observações:',
    'battery_opt_open_app_settings_btn': 'ABRIR CONFIGURAÇÕES DO APP (INICIALIZAÇÃO AUTOMÁTICA / SEGUNDO PLANO)',
    'battery_opt_open_battery_settings_btn': 'ABRIR CONFIGURAÇÕES DE OTIMIZAÇÃO DE BATERIA',
    'battery_opt_quick_buttons': 'Botões rápidos:',
    'battery_opt_request_ignore_btn': 'SOLICITAR "IGNORAR OTIMIZAÇÃO DE BATERIA"',
    'battery_opt_steps_generic': '\nAndroid genérico:\n1) Configurações → Bateria → Otimização de bateria\n2) Encontre este app → defina como "Não otimizar"\n3) Configurações → Aplicativos → (este app) → Bateria → Permitir atividade em segundo plano\n4) Se houver configurações de inicialização automática, ative-as para este app\n',
    'battery_opt_steps_huawei': '\nHuawei / Honor:\n1) Configurações → Bateria → Inicialização de apps\n2) Encontre este app → defina como "Gerenciar manualmente"\n3) Ative: Inicialização automática, Inicialização secundária, Executar em segundo plano\n',
    'battery_opt_steps_oppo': '\nOPPO / realme / OnePlus:\n1) Configurações → Bateria → Mais configurações de bateria / Gerenciamento de bateria de apps\n2) Encontre este app → Permitir atividade em segundo plano\n3) Ative também a inicialização automática (geralmente em: Configurações → Aplicativos → Inicialização automática)\n',
    'battery_opt_steps_samsung': '\nSamsung:\n1) Configurações → Bateria e cuidados do dispositivo → Bateria\n2) Limites de uso em segundo plano → Apps que nunca hibernam → adicione este app\n3) Verifique também: Configurações → Aplicativos → (este app) → Bateria → Permitir atividade em segundo plano\n',
    'battery_opt_steps_transsion': '\nInfinix / Tecno / itel (HiOS/XOS):\n1) Configurações → Bateria / Power Marathon → desative a economia agressiva para este app\n2) Configurações → Aplicativos → (este app) → Bateria → Permitir atividade em segundo plano\n3) Ative a inicialização automática / em segundo plano, se disponível\n4) Adicione também o app à lista branca em "Phone Master" / "Device Manager"\n',
    'battery_opt_title': 'Corrigir Transmissão em Segundo Plano (Otimização de Bateria)',
