    'battery_opt_close': 'Kapat',
    'battery_opt_device_prefix': 'Cihaz: ',
    'battery_opt_intro': 'Oyunu açtığınızda yayınınız duruyorsa, telefonunuz uygulamayı arka planda kapatıyor demektir.\nBu adımları bir kez uygulayın:',
    'battery_opt_notes_body': '• Bazı oyunlar ekran kaydını engeller (korumalı içerik). Bu durumda izleyiciler siyah ekran görebilir.\n• Canlı yayın sırasında yayın bildirimini AÇIK tutun.\n• En iyi sonuç için canlı yayın sırasında uygulamayı "Zorla durdur" yapmayın.',
    'battery_opt_notes_title': 'Notlar:',
    'battery_opt_open_app_settings_btn': 'UYGULAMA AYARLARINI AÇ (OTOMATİK BAŞLATMA / ARKA PLAN)',
    'battery_opt_open_battery_settings_btn': 'PİL OPTİMİZASYONU AYARLARINI AÇ',
    'battery_opt_quick_buttons': 'Hızlı düğmeler:',
    'battery_opt_request_ignore_btn': '"PİL OPTİMİZASYONUNU YOK SAY" İSTE',
    'battery_opt_steps_generic': '\nGenel Android:\n1) Ayarlar → Pil → Pil optimizasyonu\n2) Bu uygulamayı bulun → "Optimize etme" olarak ayarlayın\n3) Ayarlar → Uygulamalar → (bu uygulama) → Pil → Arka plan etkinliğine izin ver\n4) Otomatik başlatma ayarlarınız varsa bu uygulama için etkinleştirin\n',
    'battery_opt_steps_huawei': '\nHuawei / Honor:\n1) Ayarlar → Pil → Uygulama başlatma\n2) Bu uygulamayı bulun → "Manuel olarak yönet" olarak ayarlayın\n3) Şunları etkinleştirin: Otomatik başlatma, İkincil başlatma, Arka planda çalışma\n',
    'battery_opt_steps_oppo': '\nOPPO / realme / OnePlus:\n1) Ayarlar → Pil → Diğer pil ayarları / Uygulama pil yönetimi\n2) Bu uygulamayı bulun → Arka plan etkinliğine izin ver\n3) Otomatik başlatmayı da etkinleştirin (genellikle: Ayarlar → Uygulamalar → Otomatik başlatma)\n',
    'battery_opt_steps_samsung': '\nSamsung:\n1) Ayarlar → Pil ve cihaz bakımı → Pil\n2) Arka plan kullanım sınırları → Asla uyumayan uygulamalar → bu uygulamayı ekleyin\n3) Ayrıca kontrol edin: Ayarlar → Uygulamalar → (bu uygulama) → Pil → Arka plan etkinliğine izin ver\n',
    'battery_opt_steps_transsion': '\nInfinix / Tecno / itel (HiOS/XOS):\n1) Ayarlar → Pil / Power Marathon → bu uygulama için agresif tasarrufu kapatın\n2) Ayarlar → Uygulamalar → (bu uygulama) → Pil → Arka plan etkinliğine izin ver\n3) Varsa Otomatik başlatma / Arka planda başlatmayı etkinleştirin\n4) Uygulamayı "Phone Master" / "Device Manager" içinde de beyaz listeye ekleyin\n',
